templates.template:
/* =============================================================================
   Assassin's Path — a XenForo 2.3 port of the ProBoards skin by Silent of IncrediBAD.
   Black page, the Assassin's Creed header, a white framed column with a brown rounded
   menu bar, brown title bars and the assassin crest as the forum icon.
   The skin's images are embedded below, so the style needs no uploads.
   ============================================================================= */

@ap-brown: #584a45;
@ap-titlebg: linear-gradient(180deg, #837975 0%, #716561 45%, #584a45 50%, #584a45 100%);
@ap-border: #d3d3d3;

html
{
	background: #000;
}

body,
.p-pageWrapper
{
	background: transparent;
}

// ---- The framed 900px column: header art, white middle, rounded base ----------------

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 900px;
}

.p-header,
.p-nav,
.p-sectionLinks,
.p-body
{
	background: transparent;
	border: none;
}

.p-header-content
{
	height: 250px;
	padding: 0;
	background: url("data:image/jpeg;base64,") center bottom / 900px 250px no-repeat;
}

// The header art replaces the logo. Delete this rule to show the logo from Style properties.
.p-header-logo
{
	display: none;
}

.p-navSticky,
.p-navSticky.is-sticky
{
	position: static !important;
}

.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner
{
	background: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA4QAAAAKCAYAAADsHJAOAAAAdElEQVR42u3XQRWCUAAAwcUCRCCBETyQhkyk4UAEExjBBJ+jGXjORNjbTmOMfo65Wqpn9ap1CwAAgJs79uqs3tWn1m/VQxgAAID/ZAgBAAAMIQAAAIYQAAAAQwgAAIAhBAAAwBACAABgCAEAADCEAAAA3McFA20KEV0/MKYAAAAASUVORK5CYII=") center top / 900px 10px repeat-y;
	padding-left: 40px;
	padding-right: 40px;
}

.p-body-inner
{
	color: #222;
	padding-bottom: 20px;
}

// Brown rounded menu bar
.p-nav
{
	color: #fff;
}

// The menu bar is drawn across the whole nav row, over the white column
.p-nav-inner
{
	min-height: 37px;
	padding: 6px 60px;
	background:
		url("data:image/png;base64,") center 6px / 800px 25px no-repeat,
		url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA4QAAAAKCAYAAADsHJAOAAAAdElEQVR42u3XQRWCUAAAwcUCRCCBETyQhkyk4UAEExjBBJ+jGXjORNjbTmOMfo65Wqpn9ap1CwAAgJs79uqs3tWn1m/VQxgAAID/ZAgBAAAMIQAAAIYQAAAAQwgAAIAhBAAAwBACAABgCAEAADCEAAAA3McFA20KEV0/MKYAAAAASUVORK5CYII=") center top / 900px 10px repeat-y;
}

.p-nav-scroller,
.p-nav-opposite
{
	height: 25px;
	align-items: center;
}

.p-nav-list
{
	justify-content: center;
	width: 100%;

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: #fff;
		font-weight: 700;
		font-size: 12px;
		line-height: 15px;
		padding-top: 5px;
		padding-bottom: 5px;

		&:hover
		{
			color: #fff;
			text-decoration: underline;
		}
	}

	.p-navEl.is-selected
	{
		background: rgba(255, 255, 255, .12);
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: #fff;
	font-size: 12px;

	&:hover
	{
		background: rgba(255, 255, 255, .12);
		color: #fff;
		text-decoration: none;
	}
}

.p-sectionLinks-inner a
{
	color: @ap-brown;
}

.p-breadcrumbs,
.p-breadcrumbs a
{
	font-size: 10px;
	color: @ap-brown;
}

// ---- Blocks: brown title bars, light grey rows, thin silver borders -------------------

.block-container
{
	background: #f0f0f0;
	border: 1px solid @ap-border;
	border-radius: 0;
}

.block-header,
.block-minorHeader,
.block-tabHeader,
.menu-header,
.menu-tabHeader,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: @ap-titlebg;
	border-bottom: 1px solid @ap-border;
	color: #fff;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: #fff;
	}

	.block-desc
	{
		color: rgba(255, 255, 255, .8);
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: rgba(255, 255, 255, .7);

	&:hover,
	&.is-active
	{
		color: #fff;
		border-color: #fff;
	}
}

.block-footer
{
	background: @ap-titlebg;
	border-top-color: @ap-border;
	color: #fff;

	a
	{
		color: #fff;
	}
}

.node + .node
{
	border-top: 1px solid @ap-border;
}

.node-body
{
	background: #f4f4f4;
}

.node-title a
{
	color: @ap-brown;
	font-weight: 700;
}

.node-description
{
	color: #222;
}

// The assassin crest: solid when there are new posts, faded when read.
.node--forum .node-icon i
{
	display: block;
	width: 48px;
	height: 48px;
	margin: 0 auto;
	background: url("data:image/png;base64,") center / contain no-repeat;
	opacity: .45;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	opacity: 1;
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: @ap-brown;
	}
}

.structItem
{
	background: #f4f4f4;
	border-top-color: @ap-border;
}

.structItem-title a
{
	color: @ap-brown;
}

.message,
.message-cell--user
{
	border-color: @ap-border;
}

.message-cell--user
{
	background: #ececec;
}

.button.button--primary,
a.button.button--primary
{
	background: @ap-titlebg;
	border: 1px solid #3d332f;
	color: #fff;

	&:hover
	{
		background: linear-gradient(180deg, #948a86 0%, #7d716d 45%, #66574f 50%, #66574f 100%);
		color: #fff;
	}
}

// ---- Footer: the rounded base, then links and the skin credit on the black page --------

.p-footer
{
	background: transparent;
	color: #9a9a9a;

	&::before
	{
		content: '';
		display: block;
		max-width: 900px;
		height: 27px;
		margin: 0 auto;
		background: url("data:image/png;base64,") center top / 900px 27px no-repeat;
	}

	a
	{
		color: #cfc3bd;

		&:hover
		{
			color: #fff;
		}
	}
}

.p-footer-copyright::after
{
	content: "Assassin's Path skin created by Silent of IncrediBAD";
	display: block;
	margin-top: 4px;
	font-weight: 700;
}

// ---- Narrower than the 900px frame: scale the art and drop the frame edges -------------

@media (max-width: 919px)
{
	.p-header-content
	{
		height: auto;
		aspect-ratio: 900 / 250;
		background-size: 100% auto;
	}

	.p-sectionLinks-inner,
	.p-body-inner
	{
		background: #fff;
		padding-left: 10px;
		padding-right: 10px;
	}

	.p-nav-inner
	{
		padding: 0 10px;
		background: @ap-titlebg;
		border-radius: 0 0 12px 12px;
	}

	.p-footer::before
	{
		background-size: 100% 27px;
	}
}
